#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static const double V_SEG[6] = {660.0, 150.0, -1040.0, -4100.0, -9200.0, -14300.0};

#define HASH_SIZE (1 << 20)
#define HASH_MASK (HASH_SIZE - 1)

typedef struct {
    uint64_t key;
    double val;
    int best_act;
} HashEntry;

static HashEntry table[HASH_SIZE];

static inline uint64_t hash64(uint64_t x) {
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    x = x ^ (x >> 31);
    return x;
}

static inline uint64_t insert_sorted(uint64_t key, int d, int item) {
    // key holds d items of 5 bits each, sorted ascending
    uint64_t res = 0;
    int inserted = 0;
    int out_idx = 0;
    for (int i = 0; i < d; i++) {
        int cur = (key >> (i * 5)) & 31;
        if (!inserted && item <= cur) {
            res |= ((uint64_t)item) << (out_idx * 5);
            out_idx++;
            inserted = 1;
        }
        res |= ((uint64_t)cur) << (out_idx * 5);
        out_idx++;
    }
    if (!inserted) {
        res |= ((uint64_t)item) << (out_idx * 5);
    }
    return res;
}

static double dp_rec(uint64_t key, int d, int max_r, const double p[6], const double P[3][6][6], int *out_act) {
    double v_app = 0.0;
    for (int s = 0; s < 6; s++) v_app += p[s] * V_SEG[s];
    double v_stop = v_app > 0.0 ? v_app : 0.0;
    int stop_act = (v_app >= 0.0) ? 3 : 4; // 0:bureau, 1:income, 2:bank, 3:approve, 4:decline

    int r = max_r - d;
    if (r == 0) {
        if (out_act) *out_act = stop_act;
        return v_stop;
    }

    double v_pi = 660.0 * p[0] + 150.0 * p[1];
    if (v_pi - v_stop <= 20.0) {
        if (out_act) *out_act = stop_act;
        return v_stop;
    }

    uint64_t full_key = key | (((uint64_t)d) << 45) | (1ULL << 50);
    uint64_t h = hash64(full_key) & HASH_MASK;
    if (table[h].key == full_key) {
        if (out_act) *out_act = table[h].best_act;
        return table[h].val;
    }

    double best_val = v_stop;
    int best_act = stop_act;

    // Order checks: income (1), bank (2), bureau (0) to maximize pruning
    const int check_order[3] = {1, 2, 0};

    for (int ci = 0; ci < 3; ci++) {
        int k = check_order[ci];
        double joint[6][6];
        double prob_b[6] = {0};
        for (int s = 0; s < 6; s++) {
            double ps = p[s];
            for (int b = 0; b < 6; b++) {
                double j = ps * P[k][s][b];
                joint[s][b] = j;
                prob_b[b] += j;
            }
        }

        // Upper bound for check k starts at -20 + v_pi
        double ub = -20.0 + v_pi;
        if (ub <= best_val + 1e-12) continue;

        double val_k = -20.0;
        int pruned = 0;
        // Iterate bands from 5 down to 0
        for (int b = 5; b >= 0; b--) {
            double pb = prob_b[b];
            if (pb > 1e-13) {
                double post[6];
                double inv_pb = 1.0 / pb;
                for (int s = 0; s < 6; s++) post[s] = joint[s][b] * inv_pb;
                double post_pi = 660.0 * post[0] + 150.0 * post[1];
                uint64_t next_key = insert_sorted(key, d, k * 6 + b);
                double sub_v = dp_rec(next_key, d + 1, max_r, post, P, NULL);
                val_k += pb * sub_v;
                ub -= pb * (post_pi - sub_v);
                if (ub <= best_val + 1e-12 && d > 0) {
                    // Wait: only prune if we don't need exact Q-values at root d==0!
                    pruned = 1;
                    break;
                }
            }
        }
        if (!pruned && val_k > best_val) {
            best_val = val_k;
            best_act = k;
        }
    }

    table[h].key = full_key;
    table[h].val = best_val;
    table[h].best_act = best_act;
    if (out_act) *out_act = best_act;
    return best_val;
}

void solve_root(const double prior[6], const double P[3][6][6], int max_r, double out_q[5], int *best_act) {
    memset(table, 0, sizeof(table));
    double v_app = 0.0;
    for (int s = 0; s < 6; s++) v_app += prior[s] * V_SEG[s];
    out_q[3] = v_app; // approve
    out_q[4] = 0.0;   // decline

    if (max_r == 0) {
        out_q[0] = out_q[1] = out_q[2] = -1e9;
        *best_act = (v_app >= 0.0) ? 3 : 4;
        return;
    }

    for (int k = 0; k < 3; k++) {
        double joint[6][6];
        double prob_b[6] = {0};
        for (int s = 0; s < 6; s++) {
            for (int b = 0; b < 6; b++) {
                joint[s][b] = prior[s] * P[k][s][b];
                prob_b[b] += joint[s][b];
            }
        }
        double val_k = -20.0;
        for (int b = 0; b < 6; b++) {
            double pb = prob_b[b];
            if (pb > 1e-13) {
                double post[6];
                for (int s = 0; s < 6; s++) post[s] = joint[s][b] / pb;
                uint64_t next_key = (uint64_t)(k * 6 + b);
                double sub_v = dp_rec(next_key, 1, max_r, post, P, NULL);
                val_k += pb * sub_v;
            }
        }
        out_q[k] = val_k;
    }

    int ba = 4;
    double bv = out_q[4];
    if (out_q[3] >= bv) { bv = out_q[3]; ba = 3; }
    for (int k = 0; k < 3; k++) {
        if (out_q[k] > bv) { bv = out_q[k]; ba = k; }
    }
    *best_act = ba;
}

