    double res_val = 0.0;
    if (act_est == 3) {
        double v_app_true = 0.0;
        for (int s = 0; s < 6; s++) v_app_true += p_true[s] * V_SEG[s];
        res_val = v_app_true;
    } else if (act_est == 4) {
        res_val = 0.0;
    } else {
        int k = act_est;
        double val = -20.0;
        for (int b = 0; b < 6; b++) {
            double pb_true = 0.0, pb_est = 0.0;
            double post_true[6], post_est[6];
            for (int s = 0; s < 6; s++) {
                post_true[s] = p_true[s] * P_true[k][s][b];
                pb_true += post_true[s];
                post_est[s] = p_est[s] * P_est[k][s][b];
                pb_est += post_est[s];
            }
            if (pb_true > 1e-13) {
                for (int s = 0; s < 6; s++) post_true[s] /= pb_true;
                if (pb_est > 1e-13) {
                    for (int s = 0; s < 6; s++) post_est[s] /= pb_est;
                } else {
                    for (int s = 0; s < 6; s++) post_est[s] = post_true[s];
                }
                uint64_t next_key = insert_sorted(key, d, k * 6 + b);
                val += pb_true * traverse_est(next_key, d + 1, max_r, post_true, post_est, P_true, P_est);
            }
        }
        res_val = val;
    }
    table_trav[h].key = full_key;
    table_trav[h].val = res_val;
    return res_val;
}

double eval_policy_value(const double prior[6], const double P_true[3][6][6], const double P_est[3][6][6], int max_r) {
    memset(table_est, 0, sizeof(table_est));
    memset(table_trav, 0, sizeof(table_trav));
    dp_est_populate(0, 0, max_r, prior, P_est);
    return traverse_est(0, 0, max_r, prior, prior, P_true, P_est);
}
